    '%s import' => 'importar %s',
    '%s is invalid. Please enter an integer between %s and %s.' => '%s no es válido. Introduce un número entre %s y %s.',
    '(click to open "Generators" page)' => '(haz clic para abrir la pagina “Generadores”)',
