  'AdminInternationalHelp' => 
  array (
    '"%s" will be replaced by a number.' => '"%s" será reemplazado por un número.',
    '"%s" will be replaced by a string.' => '"%s" será reemplazado por una cadena.',
    '(Experimental: your theme must be compliant with RTL languages).' => '(Experimental: el tema debe ser compatible con los idiomas RTL).',
    '- Combine: Combine taxes (e.g.: 10% + 5% = 15%)' => '- Combinar: combinar impuestos (ej.: 10% + 5% = 15%)',
    '- One after another: Apply taxes one after another (e.g.: 100 + 10% => 110 + 5% = 115.5)' => '- Una tras otra: Aplica las tasas una después de otra (p. ej.: 100 + 10 % => 110 + 5 % = 115,5)',
